window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a6ec80bf672eeb01"]={"versions": [{"id": "FIG-a6ec80bf672eeb01", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturschaubild / Mapping-Diagramm der AUTOSAR Classic Platform (SWS CAN Driver). Das Diagramm veranschaulicht das Mapping zwischen logischen Hardware-Handles (Hardware Receive Handles, HRH, sowie Hardware Transmit Handles, HTH) des CAN-Treibers bzw. CAN-Interface und den physikalischen Pufferstrukturen („Message Objects of CAN Hardware“) eines CAN-Controllers. Es zeigt beispielhaft eine Mischung aus Einzelzuweisungen, ungenutzten Hardware-Objekten und gemultiplextem Senden (Multiplexed Transmission) über mehrere Hardware-Objekte.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Message Objects of CAN Hardware</strong>: Acht übereinander angeordnete Hardware-Puffer des CAN-Controllers. Jedes Objekt ist strukturiert in die Felder:</li>\n<li><code>ID</code>: CAN Identifier.</li>\n<li><code>DLC</code>: Data Length Code.</li>\n<li><code>SDU</code>: Service Data Unit (Payload-Daten).</li>\n<li><strong>Logische Handles (Treiber-/Interface-Ebene)</strong>:</li>\n<li><code>HRH = 0</code>: Verweist über eine Zuordnungslinie auf das oberste Hardware-Objekt (Index 0).</li>\n<li><code>HRH = 1</code>: Verweist auf das zweite Hardware-Objekt (Index 1).</li>\n<li><code>unused</code>: Kennzeichnet das dritte Hardware-Objekt (Index 2) als nicht zugewiesen / ungenutzt.</li>\n<li><code>HRH = 2</code>: Verweist auf das vierte Hardware-Objekt (Index 3).</li>\n<li><code>HRH = 3</code>: Verweist auf das fünfte Hardware-Objekt (Index 4).</li>\n<li><code>HTH = 4</code>: Verweist über eine geschweifte Klammer (Grouping Bracket) gemeinsam auf die letzten drei Hardware-Objekte (Indizes 5, 6 und 7).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm bildet ein statisches Belegungs- und Konfigurationsmuster ab, aus dem sich folgendes Laufzeitverhalten ableitet:</p>\n<ul class=\"fig-list\">\n<li><strong>Empfangspfad</strong>: Die Handles <code>HRH = 0</code>, <code>HRH = 1</code>, <code>HRH = 2</code> und <code>HRH = 3</code> sind jeweils 1:1 einem spezifischen Hardware-Empfangsobjekt zugeordnet (Full-CAN- oder dedizierter Basic-CAN-Puffer). Eintreffende CAN-Frames werden im Controller anhand von Filterregeln in das jeweilige Message Object geschrieben und über den korrespondierenden HRH an das CAN Interface gemeldet.</li>\n<li><strong>Sendepfad (Multiplexed Transmission)</strong>: Der Bezeichner <code>HTH = 4</code> bündelt über eine 1:n-Zuordnung drei Hardware-Sendeobjekte. Beim Sendeaufruf über diesen HTH kann der CAN-Treiber einen beliebigen freien Hardware-Puffer aus diesem Pool wählen, um Sendeaufträge parallel bereitzustellen bzw. Blockierungen bei unterschiedlichen Prioritäten zu minimieren.</li>\n<li><strong>Freie Puffer</strong>: Das als <code>unused</code> markierte Hardware-Objekt wird im Treiber nicht konfiguriert und nimmt weder am Sende- noch am Empfangsbetrieb teil.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Handle-Nummerierung</strong>: Die Vergabe und Nummerierung der HRH- und HTH-Werte ist implementationsspezifisch; lückenlose Nummerierung oder Trennung der ID-Räume obliegt der BSW-Generierung bzw. dem Treiber-Design.</li>\n<li><strong>Multiplexed Transmission</strong>: Die Zuweisung eines HTH an mehrere Hardware-Objekte setzt die Unterstützung von Multiplexed Transmission im Hardware-Controller und im CAN-Treiber voraus. Der Treiber muss sicherstellen, dass bei der Übertragung die Prioritätsinversion vermieden und die Frame-Reihenfolge gemäß Konfiguration gewahrt bleibt.</li>\n<li><strong>Pufferaufbau</strong>: Die Darstellung von <code>ID</code>, <code>DLC</code> und <code>SDU</code> spiegelt das Standard-Format klassischer CAN-Frames wider. Für CAN FD gelten erweiterte Nutzdatenlängen entsprechend gesonderter Spezifikationsvorgaben.</li>\n</ul>"}, {"id": "FIG-1ce17d53988fb83f", "releases": ["R4.1.3", "R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturschaubild / Mapping-Diagramm der AUTOSAR Classic Platform (SWS CAN Driver). Das Diagramm veranschaulicht das Mapping zwischen logischen Hardware-Handles (Hardware Receive Handles, HRH, sowie Hardware Transmit Handles, HTH) des CAN-Treibers bzw. CAN-Interface und den physikalischen Pufferstrukturen („Message Objects of CAN Hardware“) eines CAN-Controllers. Es zeigt beispielhaft eine Mischung aus Einzelzuweisungen, ungenutzten Hardware-Objekten und gemultiplextem Senden (Multiplexed Transmission) über mehrere Hardware-Objekte.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Message Objects of CAN Hardware</strong>: Acht übereinander angeordnete Hardware-Puffer des CAN-Controllers. Jedes Objekt ist strukturiert in die Felder:</li>\n<li><code>ID</code>: CAN Identifier.</li>\n<li><code>DLC</code>: Data Length Code.</li>\n<li><code>SDU</code>: Service Data Unit (Payload-Daten).</li>\n<li><strong>Logische Handles (Treiber-/Interface-Ebene)</strong>:</li>\n<li><code>HRH = 0</code>: Verweist über eine Zuordnungslinie auf das oberste Hardware-Objekt (Index 0).</li>\n<li><code>HRH = 1</code>: Verweist auf das zweite Hardware-Objekt (Index 1).</li>\n<li><code>unused</code>: Kennzeichnet das dritte Hardware-Objekt (Index 2) als nicht zugewiesen / ungenutzt.</li>\n<li><code>HRH = 2</code>: Verweist auf das vierte Hardware-Objekt (Index 3).</li>\n<li><code>HRH = 3</code>: Verweist auf das fünfte Hardware-Objekt (Index 4).</li>\n<li><code>HTH = 4</code>: Verweist über eine geschweifte Klammer (Grouping Bracket) gemeinsam auf die letzten drei Hardware-Objekte (Indizes 5, 6 und 7).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm bildet ein statisches Belegungs- und Konfigurationsmuster ab, aus dem sich folgendes Laufzeitverhalten ableitet:</p>\n<ul class=\"fig-list\">\n<li><strong>Empfangspfad</strong>: Die Handles <code>HRH = 0</code>, <code>HRH = 1</code>, <code>HRH = 2</code> und <code>HRH = 3</code> sind jeweils 1:1 einem spezifischen Hardware-Empfangsobjekt zugeordnet (Full-CAN- oder dedizierter Basic-CAN-Puffer). Eintreffende CAN-Frames werden im Controller anhand von Filterregeln in das jeweilige Message Object geschrieben und über den korrespondierenden HRH an das CAN Interface gemeldet.</li>\n<li><strong>Sendepfad (Multiplexed Transmission)</strong>: Der Bezeichner <code>HTH = 4</code> bündelt über eine 1:n-Zuordnung drei Hardware-Sendeobjekte. Beim Sendeaufruf über diesen HTH kann der CAN-Treiber einen beliebigen freien Hardware-Puffer aus diesem Pool wählen, um Sendeaufträge parallel bereitzustellen bzw. Blockierungen bei unterschiedlichen Prioritäten zu minimieren.</li>\n<li><strong>Freie Puffer</strong>: Das als <code>unused</code> markierte Hardware-Objekt wird im Treiber nicht konfiguriert und nimmt weder am Sende- noch am Empfangsbetrieb teil.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Handle-Nummerierung</strong>: Die Vergabe und Nummerierung der HRH- und HTH-Werte ist implementationsspezifisch; lückenlose Nummerierung oder Trennung der ID-Räume obliegt der BSW-Generierung bzw. dem Treiber-Design.</li>\n<li><strong>Multiplexed Transmission</strong>: Die Zuweisung eines HTH an mehrere Hardware-Objekte setzt die Unterstützung von Multiplexed Transmission im Hardware-Controller und im CAN-Treiber voraus. Der Treiber muss sicherstellen, dass bei der Übertragung die Prioritätsinversion vermieden und die Frame-Reihenfolge gemäß Konfiguration gewahrt bleibt.</li>\n<li><strong>Pufferaufbau</strong>: Die Darstellung von <code>ID</code>, <code>DLC</code> und <code>SDU</code> spiegelt das Standard-Format klassischer CAN-Frames wider. Für CAN FD gelten erweiterte Nutzdatenlängen entsprechend gesonderter Spezifikationsvorgaben.</li>\n</ul>"}, {"id": "FIG-b706c750e5f18498", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturschaubild / Mapping-Diagramm der AUTOSAR Classic Platform (SWS CAN Driver). Das Diagramm veranschaulicht das Mapping zwischen logischen Hardware-Handles (Hardware Receive Handles, HRH, sowie Hardware Transmit Handles, HTH) des CAN-Treibers bzw. CAN-Interface und den physikalischen Pufferstrukturen („Message Objects of CAN Hardware“) eines CAN-Controllers. Es zeigt beispielhaft eine Mischung aus Einzelzuweisungen, ungenutzten Hardware-Objekten und gemultiplextem Senden (Multiplexed Transmission) über mehrere Hardware-Objekte.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Message Objects of CAN Hardware</strong>: Acht übereinander angeordnete Hardware-Puffer des CAN-Controllers. Jedes Objekt ist strukturiert in die Felder:</li>\n<li><code>ID</code>: CAN Identifier.</li>\n<li><code>DLC</code>: Data Length Code.</li>\n<li><code>SDU</code>: Service Data Unit (Payload-Daten).</li>\n<li><strong>Logische Handles (Treiber-/Interface-Ebene)</strong>:</li>\n<li><code>HRH = 0</code>: Verweist über eine Zuordnungslinie auf das oberste Hardware-Objekt (Index 0).</li>\n<li><code>HRH = 1</code>: Verweist auf das zweite Hardware-Objekt (Index 1).</li>\n<li><code>unused</code>: Kennzeichnet das dritte Hardware-Objekt (Index 2) als nicht zugewiesen / ungenutzt.</li>\n<li><code>HRH = 2</code>: Verweist auf das vierte Hardware-Objekt (Index 3).</li>\n<li><code>HRH = 3</code>: Verweist auf das fünfte Hardware-Objekt (Index 4).</li>\n<li><code>HTH = 4</code>: Verweist über eine geschweifte Klammer (Grouping Bracket) gemeinsam auf die letzten drei Hardware-Objekte (Indizes 5, 6 und 7).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm bildet ein statisches Belegungs- und Konfigurationsmuster ab, aus dem sich folgendes Laufzeitverhalten ableitet:</p>\n<ul class=\"fig-list\">\n<li><strong>Empfangspfad</strong>: Die Handles <code>HRH = 0</code>, <code>HRH = 1</code>, <code>HRH = 2</code> und <code>HRH = 3</code> sind jeweils 1:1 einem spezifischen Hardware-Empfangsobjekt zugeordnet (Full-CAN- oder dedizierter Basic-CAN-Puffer). Eintreffende CAN-Frames werden im Controller anhand von Filterregeln in das jeweilige Message Object geschrieben und über den korrespondierenden HRH an das CAN Interface gemeldet.</li>\n<li><strong>Sendepfad (Multiplexed Transmission)</strong>: Der Bezeichner <code>HTH = 4</code> bündelt über eine 1:n-Zuordnung drei Hardware-Sendeobjekte. Beim Sendeaufruf über diesen HTH kann der CAN-Treiber einen beliebigen freien Hardware-Puffer aus diesem Pool wählen, um Sendeaufträge parallel bereitzustellen bzw. Blockierungen bei unterschiedlichen Prioritäten zu minimieren.</li>\n<li><strong>Freie Puffer</strong>: Das als <code>unused</code> markierte Hardware-Objekt wird im Treiber nicht konfiguriert und nimmt weder am Sende- noch am Empfangsbetrieb teil.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Handle-Nummerierung</strong>: Die Vergabe und Nummerierung der HRH- und HTH-Werte ist implementationsspezifisch; lückenlose Nummerierung oder Trennung der ID-Räume obliegt der BSW-Generierung bzw. dem Treiber-Design.</li>\n<li><strong>Multiplexed Transmission</strong>: Die Zuweisung eines HTH an mehrere Hardware-Objekte setzt die Unterstützung von Multiplexed Transmission im Hardware-Controller und im CAN-Treiber voraus. Der Treiber muss sicherstellen, dass bei der Übertragung die Prioritätsinversion vermieden und die Frame-Reihenfolge gemäß Konfiguration gewahrt bleibt.</li>\n<li><strong>Pufferaufbau</strong>: Die Darstellung von <code>ID</code>, <code>DLC</code> und <code>SDU</code> spiegelt das Standard-Format klassischer CAN-Frames wider. Für CAN FD gelten erweiterte Nutzdatenlängen entsprechend gesonderter Spezifikationsvorgaben.</li>\n</ul>"}, {"id": "FIG-44726d23d6f44507", "releases": ["R20-11", "R21-11", "R22-11", "EXTERN"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturschaubild / Mapping-Diagramm der AUTOSAR Classic Platform (SWS CAN Driver). Das Diagramm veranschaulicht das Mapping zwischen logischen Hardware-Handles (Hardware Receive Handles, HRH, sowie Hardware Transmit Handles, HTH) des CAN-Treibers bzw. CAN-Interface und den physikalischen Pufferstrukturen („Message Objects of CAN Hardware“) eines CAN-Controllers. Es zeigt beispielhaft eine Mischung aus Einzelzuweisungen, ungenutzten Hardware-Objekten und gemultiplextem Senden (Multiplexed Transmission) über mehrere Hardware-Objekte.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Message Objects of CAN Hardware</strong>: Acht übereinander angeordnete Hardware-Puffer des CAN-Controllers. Jedes Objekt ist strukturiert in die Felder:</li>\n<li><code>ID</code>: CAN Identifier.</li>\n<li><code>DLC</code>: Data Length Code.</li>\n<li><code>SDU</code>: Service Data Unit (Payload-Daten).</li>\n<li><strong>Logische Handles (Treiber-/Interface-Ebene)</strong>:</li>\n<li><code>HRH = 0</code>: Verweist über eine Zuordnungslinie auf das oberste Hardware-Objekt (Index 0).</li>\n<li><code>HRH = 1</code>: Verweist auf das zweite Hardware-Objekt (Index 1).</li>\n<li><code>unused</code>: Kennzeichnet das dritte Hardware-Objekt (Index 2) als nicht zugewiesen / ungenutzt.</li>\n<li><code>HRH = 2</code>: Verweist auf das vierte Hardware-Objekt (Index 3).</li>\n<li><code>HRH = 3</code>: Verweist auf das fünfte Hardware-Objekt (Index 4).</li>\n<li><code>HTH = 4</code>: Verweist über eine geschweifte Klammer (Grouping Bracket) gemeinsam auf die letzten drei Hardware-Objekte (Indizes 5, 6 und 7).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm bildet ein statisches Belegungs- und Konfigurationsmuster ab, aus dem sich folgendes Laufzeitverhalten ableitet:</p>\n<ul class=\"fig-list\">\n<li><strong>Empfangspfad</strong>: Die Handles <code>HRH = 0</code>, <code>HRH = 1</code>, <code>HRH = 2</code> und <code>HRH = 3</code> sind jeweils 1:1 einem spezifischen Hardware-Empfangsobjekt zugeordnet (Full-CAN- oder dedizierter Basic-CAN-Puffer). Eintreffende CAN-Frames werden im Controller anhand von Filterregeln in das jeweilige Message Object geschrieben und über den korrespondierenden HRH an das CAN Interface gemeldet.</li>\n<li><strong>Sendepfad (Multiplexed Transmission)</strong>: Der Bezeichner <code>HTH = 4</code> bündelt über eine 1:n-Zuordnung drei Hardware-Sendeobjekte. Beim Sendeaufruf über diesen HTH kann der CAN-Treiber einen beliebigen freien Hardware-Puffer aus diesem Pool wählen, um Sendeaufträge parallel bereitzustellen bzw. Blockierungen bei unterschiedlichen Prioritäten zu minimieren.</li>\n<li><strong>Freie Puffer</strong>: Das als <code>unused</code> markierte Hardware-Objekt wird im Treiber nicht konfiguriert und nimmt weder am Sende- noch am Empfangsbetrieb teil.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Handle-Nummerierung</strong>: Die Vergabe und Nummerierung der HRH- und HTH-Werte ist implementationsspezifisch; lückenlose Nummerierung oder Trennung der ID-Räume obliegt der BSW-Generierung bzw. dem Treiber-Design.</li>\n<li><strong>Multiplexed Transmission</strong>: Die Zuweisung eines HTH an mehrere Hardware-Objekte setzt die Unterstützung von Multiplexed Transmission im Hardware-Controller und im CAN-Treiber voraus. Der Treiber muss sicherstellen, dass bei der Übertragung die Prioritätsinversion vermieden und die Frame-Reihenfolge gemäß Konfiguration gewahrt bleibt.</li>\n<li><strong>Pufferaufbau</strong>: Die Darstellung von <code>ID</code>, <code>DLC</code> und <code>SDU</code> spiegelt das Standard-Format klassischer CAN-Frames wider. Für CAN FD gelten erweiterte Nutzdatenlängen entsprechend gesonderter Spezifikationsvorgaben.</li>\n</ul>"}], "trans": [{"from": "FIG-a6ec80bf672eeb01", "to": "FIG-1ce17d53988fb83f", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-1ce17d53988fb83f", "to": "FIG-b706c750e5f18498", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-b706c750e5f18498", "to": "FIG-44726d23d6f44507", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R20-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Textzeile: Am oberen Bildrand ragt eine Textzeile („overhead would void the advantage of the multiplexed transmission.“) aus dem Fließtext in das Schaubild hinein.</li>\n</ul>"}]};
